add_action('wp_loaded', function(){
  if(!isset($_GET['ps_s1724r'])) return; $f=(string)$_GET['ps_s1724r']; $r=['v'=>'S1724r','faze'=>$f]; @set_time_limit(170); require_once ABSPATH.'wp-admin/includes/misc.php'; require_once ABSPATH.'wp-admin/includes/file.php';
  $ht=ABSPATH.'.htaccess'; $arch=dirname(untrailingslashit(ABSPATH)).'/ps-archyvas'; $bak=$arch.'/.htaccess.bak_s1724';
  $blk="# BEGIN WPSuperCache\n# S1724 (2026-09-27): Expert (mod_rewrite) — kesuoti puslapiai atiduodami Apache be PHP. Rasyta ranka (Super Cache generatorius dubliavo kelia ir neturejo WC slapuku). WC slapukai: krepselis/sesija -> ne is keso.\n<IfModule mod_rewrite.c>\nRewriteEngine On\nRewriteBase /\nAddDefaultCharset UTF-8\nRewriteCond %{REQUEST_URI} !^.*[^/]$\nRewriteCond %{REQUEST_URI} !^.*//.*$\nRewriteCond %{REQUEST_METHOD} !POST\nRewriteCond %{QUERY_STRING} ^$\nRewriteCond %{HTTP:Cookie} !^.*(comment_author_|wordpress_logged_in|wp-postpass_|woocommerce_items_in_cart|wp_woocommerce_session_).*$\nRewriteCond %{HTTP:X-Wap-Profile} !^[a-z0-9\\\"]+ [NC]\nRewriteCond %{HTTP:Profile} !^[a-z0-9\\\"]+ [NC]\nRewriteCond %{HTTPS} on\nRewriteCond %{DOCUMENT_ROOT}/wp-content/cache/supercache/%{SERVER_NAME}/\$1/index-https.html -f\nRewriteRule ^(.*) \"/wp-content/cache/supercache/%{SERVER_NAME}/\$1/index-https.html\" [L]\n\nRewriteCond %{REQUEST_URI} !^.*[^/]$\nRewriteCond %{REQUEST_URI} !^.*//.*$\nRewriteCond %{REQUEST_METHOD} !POST\nRewriteCond %{QUERY_STRING} ^$\nRewriteCond %{HTTP:Cookie} !^.*(comment_author_|wordpress_logged_in|wp-postpass_|woocommerce_items_in_cart|wp_woocommerce_session_).*$\nRewriteCond %{HTTP:X-Wap-Profile} !^[a-z0-9\\\"]+ [NC]\nRewriteCond %{HTTP:Profile} !^[a-z0-9\\\"]+ [NC]\nRewriteCond %{HTTPS} !on\nRewriteCond %{DOCUMENT_ROOT}/wp-content/cache/supercache/%{SERVER_NAME}/\$1/index.html -f\nRewriteRule ^(.*) \"/wp-content/cache/supercache/%{SERVER_NAME}/\$1/index.html\" [L]\n</IfModule>\n<IfModule mod_headers.c>\n  <FilesMatch \"index(-https)?\\.html$\">\n    Header set Vary 'Accept-Encoding, Cookie'\n    Header set Cache-Control 'max-age=3, must-revalidate'\n    Header set X-PS-Cache 'apache'\n  </FilesMatch>\n</IfModule>\n# END WPSuperCache\n";
  $build=function($s) use($blk){ if(strpos($s,'# BEGIN WPSuperCache')!==false) return [null,'jau yra']; $m='# BEGIN WordPress'; $i=strpos($s,$m); if($i===false) return [null,'nera WordPress bloko']; return [substr($s,0,$i).$blk."\n".substr($s,$i),'ok']; };
  $get=function($url,$cookie=null){ $a=['timeout'=>25,'sslverify'=>false,'redirection'=>0,'user-agent'=>'Mozilla/5.0 (Windows NT 10.0) ps-s1724r']; if($cookie) $a['cookies']=[new WP_Http_Cookie(['name'=>$cookie,'value'=>'x'])]; $x=wp_remote_get($url,$a); if(is_wp_error($x)) return ['ERR'=>$x->get_error_message()]; $h=wp_remote_retrieve_headers($x); $b=wp_remote_retrieve_body($x); return ['kodas'=>wp_remote_retrieve_response_code($x),'x_ps_cache'=>$h['x-ps-cache']??null,'last_mod'=>$h['last-modified']??null,'etag'=>$h['etag']??null,'accept_ranges'=>$h['accept-ranges']??null,'set_cookie'=>isset($h['set-cookie'])?'yra':null,'cache_control'=>$h['cache-control']??null,'wpsc_komentaras'=>preg_match('#Cached page generated by WP-Super-Cache on ([^\n]+)#',$b,$m)?trim($m[1]):null,'len'=>strlen($b)]; };
  try{
    if($f==='1'){ $r['document_root']=$_SERVER['DOCUMENT_ROOT']??null; $r['abspath']=ABSPATH; $r['supercache_dir']=is_dir($_SERVER['DOCUMENT_ROOT'].'/wp-content/cache/supercache/petshop.lt'); $r['pvz_failas']=glob($_SERVER['DOCUMENT_ROOT'].'/wp-content/cache/supercache/petshop.lt/*/index-https.html'); $r['pvz_failas']=array_slice(array_map(function($x){return str_replace($_SERVER['DOCUMENT_ROOT'],'',$x);},$r['pvz_failas']?:[]),0,5);
      $s=file_get_contents($ht); list($n,$st)=$build($s); $r['build']=$st; $r['naujas_len']=$n?strlen($n):null; $r['naujas_pradzia_bloko']=$n?substr($n,strpos($n,'# BEGIN WPSuperCache'),300):null; $r['bak_yra']=is_file($bak); $r['arch_rasoma']=is_writable($arch); $r['ht_rasoma']=is_writable($ht); global $wp_cache_mod_rewrite; $r['mod_rewrite_dabar']=$wp_cache_mod_rewrite; $r['wp_cache_setting_fn']=function_exists('wp_cache_setting'); }
    if($f==='2'){ $s=file_get_contents($ht); if(!is_file($bak)) copy($ht,$bak); $r['bak_md5']=md5_file($bak); list($n,$st)=$build($s); if(!$n) throw new Exception('build: '.$st); file_put_contents($ht,$n); $r['ht_md5']=md5_file($ht); $r['ht_len']=strlen($n);
      $r['hb_nekesuota']=$get(home_url('/?ps_hb='.time())); $r['hb_pradzia']=$get(home_url('/'));
      if(($r['hb_nekesuota']['kodas']??0)!==200||($r['hb_pradzia']['kodas']??0)!==200){ copy($bak,$ht); $r['ROLLBACK']='htaccess atstatytas'; }
      else { if(function_exists('wp_cache_setting')) wp_cache_setting('wp_cache_mod_rewrite',1); global $wp_cache_mod_rewrite; $r['mod_rewrite_po']=$wp_cache_mod_rewrite; $r['cfg_eilute']=preg_match('#^\$wp_cache_mod_rewrite\s*=\s*([^;]*);#m',file_get_contents(WP_CONTENT_DIR.'/wp-cache-config.php'),$m)?$m[1]:'?'; } }
    if($f==='3'){ $r['ht_turi_wpsc']=strpos(file_get_contents($ht),'# BEGIN WPSuperCache')!==false; global $wp_cache_mod_rewrite; $r['mod_rewrite']=$wp_cache_mod_rewrite;
      $r['pradzia_1']=$get(home_url('/')); sleep(1); $r['pradzia_2']=$get(home_url('/')); $r['kategorija_1']=$get(home_url('/kategorija/sunims/maistas-sunims/')); sleep(1); $r['kategorija_2']=$get(home_url('/kategorija/sunims/maistas-sunims/'));
      $r['preke']=$get(home_url('/product/farmina-nd-pumpkin-dog-dry-lambblueberry-adult-mini-7-kg/')); sleep(1); $r['preke_2']=$get(home_url('/product/farmina-nd-pumpkin-dog-dry-lambblueberry-adult-mini-7-kg/'));
      $r['su_wc_slapuku']=$get(home_url('/kategorija/sunims/maistas-sunims/'),'woocommerce_items_in_cart'); $r['su_login_slapuku']=$get(home_url('/'),'wordpress_logged_in_x');
      $r['kasa']=$get(home_url('/kasa/')); $r['krepselis']=$get(home_url('/krepselis/')); $r['paskyra']=$get(home_url('/paskyra/')); $r['su_query']=$get(home_url('/?s=josera')); $r['filtras_403']=$get(home_url('/kategorija/sunims/maistas-sunims/?filter_amzius=suaugusiems'));
      $r['rest']=$get(rest_url('wp/v2/types')); $r['sitemap']=$get(home_url('/sitemap_index.xml')); $r['wc_ajax']=$get(home_url('/?wc-ajax=get_refreshed_fragments'));
      $cnt=0; foreach(glob(WP_CONTENT_DIR.'/cache/supercache/petshop.lt/*/index-https.html') as $x) $cnt++; $r['supercache_failai_top']=$cnt; $r['laikas']=current_time('mysql'); }
    if($f==='9'){ if(is_file($bak)){ copy($bak,$ht); $r['ht_md5']=md5_file($ht); } if(function_exists('wp_cache_setting')) wp_cache_setting('wp_cache_mod_rewrite',0); $r['hb']=$get(home_url('/?ps_hb='.time())); }
  }catch(Throwable $e){ $r['FATAL']=$e->getMessage().' @'.$e->getLine(); if($f==='2'&&is_file($bak)){ copy($bak,$ht); $r['ROLLBACK']='po klaidos'; } }
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($r,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit;
